styl:
.pill { margin: 0; }
.pill td.pill-cell { background: {{ bg }}; border-radius: {{ radius }}px; padding: {{ padding }}; }
.pill span.pill-text { font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 700; font-size: {{ font_size }}px; line-height: 1; color: {{ text_color }}; text-transform: {{ transform }}; }
